using System.ComponentModel;
using System.Globalization;
using ModelContextProtocol.Server;
using SimplePZMapmaker.Core;
namespace SimplePZMapmaker.Web.Services;

[McpServerToolType]
public sealed class McpGameplayTools(AgentProjectStore maps,AgentWorldStore worlds,AgentZoneStore proposals,NativeLightingService lighting,GameplayCatalog gameplay,GameAssetCatalog assets,StaticModelCatalog models)
{
 [McpServerTool(Name="lighting_status",ReadOnly=true,UseStructuredContent=true),Description("Read whether authentic installed LightingJNI computation is available. It runs locally without a game session. No approximate field is substituted.")]
 public object LightingStatus()=>lighting.Status();
 [McpServerTool(Name="lighting_map_check",ReadOnly=true,UseStructuredContent=true),Description("Compute authentic lighting for a shared map at its exact revision, signed z=-32..31 and a bounded 8–64 tile crop. Returns cell RGB, vertices, warnings and engine fingerprints. Does not edit authoring. skyRgb/ambient default to .4; powered=false disables room lights. Concurrent revision changes reject stale results.")]
 public async Task<object> CheckMap(string sessionToken,long expectedRevision,int x,int y,int size=32,int level=0,double[]? skyRgb=null,double ambient=.4,bool powered=true,CancellationToken cancellation=default){var s=maps.Read(sessionToken);Check(s.Revision,expectedRevision);var result=await lighting.Check(Request(s.Project,null,null,s.Revision,x,y,size,level,skyRgb,ambient,powered),cancellation);Check(maps.Status(sessionToken).Revision,expectedRevision);return result;}
 [McpServerTool(Name="lighting_world_check",ReadOnly=true,UseStructuredContent=true),Description("Compute authentic lighting for one exact world revision and section memberId, including clipped shared buildings. Crop x/y are local section tile coordinates. Read-only, signed levels -32..31, maximum64x64 tiles.")]
 public async Task<object> CheckWorld(string sessionToken,long expectedRevision,string memberId,int x,int y,int size=32,int level=0,double[]? skyRgb=null,double ambient=.4,bool powered=true,CancellationToken cancellation=default){var s=worlds.Read(sessionToken);Check(s.Revision,expectedRevision);var result=await lighting.Check(Request(null,s.World,memberId,s.Revision,x,y,size,level,skyRgb,ambient,powered),cancellation);var status=worlds.Read(sessionToken);Check(status.Revision,expectedRevision);return result;}
 [McpServerTool(Name="lighting_draft_check",ReadOnly=true,UseStructuredContent=true),Description("Compute lighting for an isolated complete building draft without committing it. The building is placed at 8,8 on an isolated blank map; x/y are offsets from that origin. Invalid access or missing resources reject. Signed levels -32..31; crop8..64. No map mutation.")]
 public async Task<object> CheckDraft(string sessionToken,string draftId,int x=0,int y=0,int size=32,int level=0,double[]? skyRgb=null,double ambient=.4,bool powered=true,CancellationToken cancellation=default){var b=maps.ReadDraft(sessionToken,draftId).Building;b.X=b.Y=8;var p=MapGenerator.Generate(new(){Kind="blank"});p.Buildings.Add(b);return await lighting.Check(Request(p,null,null,0,checked(x+8),checked(y+8),size,level,skyRgb,ambient,powered),cancellation);}
 static NativeLightingRequest Request(MapProject? p,WorldProject? w,string? member,long revision,int x,int y,int size,int level,double[]? sky,double ambient,bool powered)=>new(){Project=p,World=w,MemberId=member,Revision=revision.ToString(CultureInfo.InvariantCulture),X=x,Y=y,Size=size,Level=level,SkyRgb=sky??[.4,.4,.4],Ambient=ambient,RoomLightsPowered=powered};
 [McpServerTool(Name="gameplay_catalog",ReadOnly=true,UseStructuredContent=true),Description("Read supported gameplay zone types and literal registered vehicle/loot distributions with original provider/dependency ownership. Never invent a vehicle distribution or execute Lua.")]
 public object Catalog()=>gameplay.Snapshot();
 [McpServerTool(Name="gameplay_zones_read",ReadOnly=true,UseStructuredContent=true),Description("Read authored gameplay zones in a shared map or world. world=true returns memberId plus local section rectangles. Use exact existing zone IDs only when replacing them.")]
 public object ReadZones(string sessionToken,bool world=false){if(world){var s=worlds.Read(sessionToken);return new{s.Revision,sections=s.World.Maps.Select(m=>new{memberId=m.Id,zones=m.Project.GameZones})};}var map=maps.Read(sessionToken);return new{map.Revision,zones=map.Project.GameZones};}
 [McpServerTool(Name="gameplay_zones_plan",UseStructuredContent=true),Description("Create an isolated validated proposal of1–64 authored zone rectangles. scope is map/world; entries contain zone and memberId (world only). Coordinates are local section tiles, z=0. New ID adds; an explicit existing ID replaces only that zone. Vehicle zones need registered distributions from gameplay_catalog. Overlap/water/buildings reject the complete batch. Source revision is unchanged; commit is separate.")]
 public AgentZoneStore.Proposal CreateZones(string sessionToken,long expectedRevision,AgentZoneStore.Entry[] entries,string scope="map",string objective="Gameplay zones"){
  if(entries is null||entries.Length is <1 or >64||entries.Any(e=>e is null||e.Zone is null))throw new ArgumentException("A zone proposal needs 1–64 complete entries.");
  var plan=new AgentZoneStore.Proposal{BaseRevision=expectedRevision,Scope=scope,Entries=NeighborhoodPlanner.Copy(entries),Objective=objective};
  if(scope=="map"){var s=maps.Read(sessionToken);Check(s.Revision,expectedRevision);if(entries.Any(e=>e.MemberId is not null))throw new ArgumentException("Map zones do not have a section owner.");ValidateMap(GameZones.ApplyProposal(s.Project,plan.Entries.Select(e=>e.Zone).ToArray()));}
  else if(scope=="world"){var s=worlds.Read(sessionToken);Check(s.Revision,expectedRevision);ApplyWorld(s.World,plan);}
  else throw new ArgumentException("Zone proposal scope must be map or world.");return proposals.Save(sessionToken,plan);
 }
 [McpServerTool(Name="gameplay_zones_plan_read",ReadOnly=true,UseStructuredContent=true),Description("Read the exact zone proposal and base revision without changing a map or world. Browser can inspect its rectangles before receiving a committed version.")]
 public AgentZoneStore.Proposal ReadPlan(string sessionToken,string proposalId)=>proposals.Read(sessionToken,proposalId);
 [McpServerTool(Name="gameplay_zones_plan_commit",UseStructuredContent=true),Description("Atomically commit a zone proposal against its base/current revision. Unknown sections, changed distributions, overlaps or stale revisions reject without writes. Browser sees this as a proposed session revision and receives it as one undoable action.")]
 public object Commit(string sessionToken,string proposalId,long expectedRevision){var plan=proposals.Read(sessionToken,proposalId);Check(plan.BaseRevision,expectedRevision);if(plan.Scope=="map"){var s=maps.Mutate(sessionToken,expectedRevision,p=>{var next=GameZones.ApplyProposal(p,plan.Entries.Select(e=>e.Zone).ToArray());ValidateMap(next);p.GameZones=next.GameZones;},"agent");return new{s.Revision,proposalId};}var world=worlds.Mutate(sessionToken,expectedRevision,w=>ApplyWorld(w,plan));return new{world.Revision,proposalId};}
 void ApplyWorld(WorldProject w,AgentZoneStore.Proposal plan){foreach(var group in plan.Entries.GroupBy(e=>e.MemberId)){var m=w.Maps.SingleOrDefault(m=>m.Id==group.Key)??throw new ArgumentException("The zone proposal references an unknown section.");m.Project=GameZones.ApplyProposal(m.Project,group.Select(e=>e.Zone).ToArray());ValidateMap(m.Project);}WorldEndpoints.Validate(w,assets,models);}
 void ValidateMap(MapProject p){gameplay.Validate(p);AssetRules.Project(p,assets);models.Validate(p);}
 static void Check(long current,long expected){if(current!=expected)throw new AgentRevisionConflict(current);}
}
